import { existsSync } from "node:fs";
import { isPrivatePreviewHandle } from "@matrix-os/contracts";

/** Restrict this slice to the owner-only host projection generated by Platform. */
export function admitsHostedBotsPrivatePreview(env: NodeJS.ProcessEnv): boolean {
  const handle = env.MATRIX_HANDLE;
  const platformUrl = env.PLATFORM_INTERNAL_URL;
  if (env.MATRIX_PREVIEW_RUNTIME !== "true" || env.MATRIX_COLLABORATION_DISABLED !== "1"
    || !handle || !isPrivatePreviewHandle(handle) || env.MATRIX_RUNTIME_SLOT !== handle
    || !platformUrl || !URL.canParse(platformUrl)) return false;

  const platform = new URL(platformUrl);
  if (platform.protocol !== "https:" || platform.username || platform.password
    || platform.pathname !== "/" || platform.search || platform.hash) return false;

  return env.MATRIX_UPDATE_MANIFEST_BASE_URL === `${platform.origin}/private-preview-updates/${handle}`;
}

// The current bundle marker selects the OSS surface but grants no authority.
export function admitsOpenMausBotPreviewBundle(
  env: NodeJS.ProcessEnv,
  markerExists: (path: string) => boolean = existsSync,
): boolean {
  return admitsHostedBotsPrivatePreview(env) && markerExists("/opt/matrix/app/MATRIX_OPENMAUSBOT_PREVIEW");
}
